<div class="patient-heading"><div><span class="eyebrow"><?= e($record['code']) ?></span><h2><?= e($record['first_name'].' '.$record['last_name']) ?></h2></div><div class="actions"><a class="button secondary" href="<?= e(url('/admin/odontogram?patient_id='.$record['patient_id'])) ?>"><?= icon('tooth',18) ?> Odontograma</a><button class="button secondary" type="button" data-print>Imprimir historia</button></div></div>
