<details class="panel form-panel" <?= $error ? 'open':'' ?>><summary>Registrar y firmar una evolución clínica</summary><p class="muted">Las entradas firmadas se conservan. Para corregir una entrada, referencia su número y explica el cambio en observaciones.</p><form method="post" class="form-grid" data-confirm="Al firmar, esta entrada quedará cerrada. Las correcciones se registrarán como entradas nuevas."><?= csrf_field() ?><input type="hidden" name="patient_id" value="<?= (int)$record['patient_id'] ?>"><?php area('medical_history','Antecedentes médicos',$_POST['medical_history'] ?? $record['medical_history']); area('dental_history','Antecedentes odontológicos',$_POST['dental_history'] ?? $record['dental_history']); area('allergies','Alergias',$_POST['allergies'] ?? $record['allergies']); foreach(['consultation_reason'=>'Motivo de consulta','evaluation'=>'Evaluación clínica','diagnosis'=>'Diagnósticos','plan'=>'Plan de tratamiento','procedures'=>'Procedimientos realizados','observation'=>'Observaciones / motivo de corrección'] as $k=>$n) area($k,$n,$_POST[$k] ?? '',!in_array($k,['procedures','observation'],true)); choose('correction_of','Corrección de entrada (opcional)',array_combine(array_column($entries,'id'),array_map(fn($x)=>'#'.$x['id'].' · '.local_date($x['created_at']),$entries)) ?: [],$_POST['correction_of'] ?? '',false); ?><label class="checkbox full"><input type="checkbox" name="confirm_sign" value="1" required> Revisé los datos y confirmo la firma de esta entrada.</label><button class="button">Firmar y cerrar entrada</button></form></details>
<section class="clinical-timeline"><h2>Evoluciones y correcciones</h2><?php foreach($entries as $entry): ?><article class="panel clinical-entry"><div class="panel-heading"><h3>Entrada #<?= (int)$entry['id'] ?><?= $entry['correction_of'] ? ' · Corrige #'.(int)$entry['correction_of']:'' ?></h3><span class="badge completed">Firmada</span></div><p class="muted"><?= local_date($entry['signed_at']) ?> · <?= e($entry['author']) ?></p><?php foreach(['consultation_reason'=>'Motivo','evaluation'=>'Evaluación','diagnosis'=>'Diagnósticos','plan'=>'Plan','procedures'=>'Procedimientos','observation'=>'Observaciones','medical_history'=>'Antecedentes médicos al firmar','dental_history'=>'Antecedentes odontológicos al firmar','allergies'=>'Alergias al firmar'] as $k=>$n): if(empty($entry[$k])) continue; ?><div><strong><?= $n ?></strong><p><?= nl2br(e($entry[$k])) ?></p></div><?php endforeach; ?></article><?php endforeach; ?><?php if(!$entries): ?><p class="empty panel">Aún no se han firmado evoluciones clínicas.</p><?php endif; ?></section>
<section class="panel form-panel"><h2>Archivos de la historia</h2><p class="muted">PDF, JPG o PNG · hasta 5 MB · almacenamiento privado</p><form method="post" enctype="multipart/form-data" class="filters" data-loading><?= csrf_field() ?><input type="hidden" name="action" value="upload"><input type="hidden" name="patient_id" value="<?= (int)$record['patient_id'] ?>"><label>Archivo<input type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png" required></label><button class="button">Adjuntar archivo</button></form><ul class="attachment-list"><?php foreach($attachments as $file): ?><li><a href="<?= e(url('/admin/attachment?id='.$file['id'])) ?>"><?= e($file['original_name']) ?></a> <small><?= local_date($file['created_at']) ?></small></li><?php endforeach; ?></ul></section>

